        s.Ok(W(50), N(1, 0, 0), 0, A(10, 200), N(0, 1, 1));
        s.Refused(D(0, 0, 1), AtmStatus.CassetteJammed);
        s.Ok(D(1, 1, 0), NoteCounts.None, 0, A(80, 200), N(1, 2, 1));
