            {
                Stock = N(
                    Math.Min(Capacity, situation.Stock.Fifties + added.Fifties),
                    Math.Min(Capacity, situation.Stock.Twenties + added.Twenties),
                    Math.Min(Capacity, situation.Stock.Tens + added.Tens)),
            };

